  "inlineSchema": "// Esquema de base de datos del marketplace de mascotas\n// Motor: SQLite por defecto (fácil de correr local). Para producción,\n// cambiar \"provider\" a \"postgresql\" y DATABASE_URL en el .env por una\n// URL de Postgres (Railway, Render, Supabase, etc).\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Admin {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  name         String\n  createdAt    DateTime @default(now())\n}\n\nmodel Category {\n  id        String    @id @default(cuid())\n  name      String    @unique\n  slug      String    @unique\n  imageUrl  String?\n  products  Product[]\n  createdAt DateTime  @default(now())\n}\n\nmodel Product {\n  id          String         @id @default(cuid())\n  name        String\n  slug        String         @unique\n  description String\n  price       Float\n  stock       Int            @default(0)\n  petType     String // \"perro\", \"gato\", \"otro\", etc.\n  active      Boolean        @default(true)\n  category    Category       @relation(fields: [categoryId], references: [id])\n  categoryId  String\n  images      ProductImage[]\n  orderItems  OrderItem[]\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n}\n\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  url       String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  productId String\n  position  Int     @default(0)\n}\n\nmodel Order {\n  id              String      @id @default(cuid())\n  customerName    String\n  customerEmail   String\n  customerPhone   String?\n  shippingAddress String?\n  total           Float\n  status          String      @default(\"pending\") // pending, paid, rejected, shipped, delivered, cancelled\n  paymentMethod   String? // credit_card, debit_card, transfer, etc (lo informa Mercado Pago)\n  mpPreferenceId  String?\n  mpPaymentId     String?\n  items           OrderItem[]\n  createdAt       DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n}\n\nmodel OrderItem {\n  id        String  @id @default(cuid())\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderId   String\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n  quantity  Int\n  unitPrice Float\n}\n\n// Configuración general del sitio (fila única - \"singleton\").\n// Se lee en el frontend para pintar nombre del negocio, logo, color y banner de inicio.\nmodel SiteSettings {\n  id            String   @id @default(\"singleton\")\n  businessName  String   @default(\"PetShop\")\n  logoUrl       String?\n  primaryColor  String   @default(\"#ea7c1e\")\n  heroTitle     String   @default(\"Todo para tu mascota, en un solo lugar\")\n  heroSubtitle  String   @default(\"Alimento, juguetes, higiene y accesorios para perros, gatos y más.\")\n  heroImageUrl  String?\n  // Orden de las secciones de la home, separadas por coma (ej: \"hero,banners,categories,products\")\n  sectionsOrder String   @default(\"hero,banners,categories,products\")\n  updatedAt     DateTime @updatedAt\n}\n\n// Banners promocionales que se muestran en la home (ej: ofertas, envío gratis, etc.)\nmodel Banner {\n  id        String   @id @default(cuid())\n  title     String?\n  subtitle  String?\n  imageUrl  String\n  linkUrl   String?\n  position  Int      @default(0)\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n}\n",
